def count(num):
	si = 0
	while num:
		si += num % 10
		num = num // 10
	return si
n = int(input())
cnt = 0
if n < 100:
	ra = 0
else:
	ra = n - 100
s = 0
for i in range(ra, n):
	fi = count(i)
	se = count(fi)
	s = i + fi + se
	if s == n:
		cnt += 1
	elif s < n:
		s = 0
print(cnt)
